import csv
import io


def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    csv.field_size_limit(max(csv.field_size_limit(), len(raw_csv)))
    records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=";", quotechar='"'))

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])

    used_names = set(columns)
    while len(columns) < width:
        base = "column_{}".format(len(columns) + 1)
        name = base
        suffix = 2
        while name in used_names:
            name = "{}_{}".format(base, suffix)
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
